    "summary": "此功以狴犴镇狱之威为势,千般酷刑为髓.临者如遭无间地狱之罚,诛其身,亦诛其心,在剧痛与冤屈中亲睹其罪,终至理性崩解神魂俱沸,沦为疯魔之囚.侥幸脱生之徒,亦恨自己不得其死.",
